import{_ as e,o,c as n,a2 as s}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"コネクター（Connect-It）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/self-hosted/connectors.md","filePath":"ja/self-hosted/connectors.md","lastUpdated":1792323081000}'),a={name:"ja/self-hosted/connectors.md"};function r(i,t,h,d,l,p){return o(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="コネクター-connect-it" tabindex="-1">コネクター（Connect-It） <a class="header-anchor" href="#コネクター-connect-it" aria-label="Permalink to &quot;コネクター（Connect-It）&quot;">​</a></h1><p>コネクターは、Bot に GitHub や Notion のようなサードパーティサービスのツールを使わせる仕組みです。裏側にあるのは <a href="https://github.com/memohai/connect-it" target="_blank" rel="noreferrer">Connect-It</a>——Memoh と一緒にデプロイされる併設サービスです。すべての資格情報（OAuth トークン、API Key）は Connect-It 側に保存され、Memoh が持つのはバインディング表だけです——どの Bot がどの接続に結び付いているか、ツール名前空間は何か、有効かどうか。</p><p>利用者から見ると、コネクターは単体でインストールするものではありません。<a href="./../guides/supermarket.html">アプリ</a>のコンポーネントとして App と一緒に届きます。App のマニフェストがどのコネクタータイプを使うか・必須かどうかを宣言しており、インストール後に Bot の <strong>アプリ</strong> タブで認証すれば完了です。このページの残りは運用者視点——Connect-It をどう動かすか、そして接続の裏側の仕組みです。</p><hr><h2 id="サーバー側の前提" tabindex="-1">サーバー側の前提 <a class="header-anchor" href="#サーバー側の前提" aria-label="Permalink to &quot;サーバー側の前提&quot;">​</a></h2><p>サーバーに Connect-It のエンドポイントが設定されて初めて、コネクター機能が現れます：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">connect_it</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base_url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 例 &quot;http://connect-it:8421&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_token = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # サーバー間の信頼トークン</span></span></code></pre></div><p>両方を空にすると機能は無効になります。本番環境では対応する環境変数（<code>MEMOH_CONNECT_IT_BASE_URL</code>、<code>MEMOH_CONNECT_IT_API_TOKEN</code>）の使用を推奨します。</p><p>ワンライナーの Server Deploy は、新規インストール時に同居の Connect-It を自動で立ち上げます。詳しくは <a href="./docker.html#connect-it-コネクター">Server Deploy</a> を参照してください。Connect-It が未設定の場合、コネクターに依存する App コンポーネントは「コネクターを利用できません」と表示されます。</p><hr><h2 id="認証と管理" tabindex="-1">認証と管理 <a class="header-anchor" href="#認証と管理" aria-label="Permalink to &quot;認証と管理&quot;">​</a></h2><p>コネクター付きの App をインストールすると、Bot の <strong>アプリ</strong> タブがコンポーネントとしてコネクターを一覧し、状態を表示します：<strong>認証が必要</strong>、<strong>任意</strong>、または <strong>全ワークスペースで共有</strong>。<strong>認証する</strong> をクリックしてバインディングを完了します——OAuth はポップアップで認可し（ブラウザにブロックされたら許可して再試行）、API Key 型なら資格情報フィールドに入力します。</p><p>各接続には状態が表示されます：</p><table tabindex="0"><thead><tr><th>状態</th><th>意味</th></tr></thead><tbody><tr><td><strong>接続済み</strong></td><td>正常。ツールは Bot から利用可能</td></tr><tr><td><strong>認証待ち</strong></td><td>接続はあるが OAuth が未完了。認証を済ませるか、切断する</td></tr><tr><td><strong>再認証が必要です</strong></td><td>資格情報が期限切れか取り消し。<strong>再認証</strong> をクリック</td></tr><tr><td><strong>認証に失敗しました</strong></td><td>前回の認証が失敗。<strong>再認証</strong> で再試行できる</td></tr><tr><td><strong>利用不可</strong></td><td>設定中の Connect-It にこのコネクタータイプがない</td></tr><tr><td><strong>無効</strong></td><td>停止中。ツールは Bot に渡されない</td></tr></tbody></table><p>接続は削除せずに<strong>有効化／無効化</strong>できます。<strong>切断</strong>はバインディングを Bot から外し、<strong>さらに</strong> Connect-It 側に保存された接続（資格情報を含む）も削除します——それを使っていた App は再認証が必要になります。</p><hr><h2 id="ツールはどうやって-bot-に届くか" tabindex="-1">ツールはどうやって Bot に届くか <a class="header-anchor" href="#ツールはどうやって-bot-に届くか" aria-label="Permalink to &quot;ツールはどうやって Bot に届くか&quot;">​</a></h2><p>会話の際、Memoh はその Bot の有効かつ正常な接続をすべて 1 つの MCP セッションに集約し、ツールソースとしてエージェントに渡します。コネクターのツールはワークスペースや MCP のツールと並んで現れます。</p><p>各接続はバインドの瞬間に、コネクタータイプから生成される<strong>ツール名前空間</strong>を受け取ります——GitHub 接続なら <code>github</code>、2 つ目は <code>github-2</code> です。名前空間はバインディングの生存期間中ずっと固定で、後から他の接続を増減しても、既存接続のツール名は変わりません。</p><hr><h2 id="関連ページ" tabindex="-1">関連ページ <a class="header-anchor" href="#関連ページ" aria-label="Permalink to &quot;関連ページ&quot;">​</a></h2><ul><li><a href="./../guides/supermarket.html">マーケットプレイス</a> —— アプリ（コネクターコンポーネント込み）のインストール入口。</li><li><a href="./../guides/mcp.html">MCP</a> —— MCP 接続を直接管理する。</li><li><a href="./docker.html#connect-it-コネクター">Server Deploy</a> —— Connect-It の同居デプロイ、資格情報管理、OAuth コールバックアドレス。</li></ul>`,22)])])}const k=e(a,[["render",r]]);export{g as __pageData,k as default};
